import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:provider/provider.dart';
import 'package:supabase_flutter/supabase_flutter.dart';

import '../core/clinic_theme.dart';
import '../data/clinic_scope.dart';
import 'doctor_reference_dialog.dart';

/// Scribe — ambient documentation drafts. Drafts are generated by the
/// backend agent (`draft_encounter_chart`) and appear here for practitioner
/// review: read the SOAP sections, edit in mind, mark reviewed. The scribe
/// never finalizes a note itself (CONTEXT.md — "Grounding over generation").
class ScribePage extends StatelessWidget {
  const ScribePage({super.key});

  @override
  Widget build(BuildContext context) {
    final scope = context.watch<ClinicScope>();
    final encounters = scope.stream('encounters');

    if (encounters == null) {
      return const Center(child: CircularProgressIndicator(color: ClinicTheme.malachite));
    }

    return Padding(
      padding: const EdgeInsets.all(24),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              const Text('Scribe', style: TextStyle(fontSize: 24, fontWeight: FontWeight.w800)),
              OutlinedButton.icon(
                icon: const Icon(Icons.menu_book, color: ClinicTheme.malachite, size: 16),
                label: const Text('Clinical Quick-Reference', style: TextStyle(color: ClinicTheme.malachite)),
                style: OutlinedButton.styleFrom(
                  side: const BorderSide(color: ClinicTheme.malachite),
                  padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
                ),
                onPressed: () => DoctorReferenceDialog.show(context),
              ),
            ],
          ),
          const Text(
            'Ambient drafts from exam conversations. Review, then mark reviewed — '
            'the draft never becomes the chart on its own.',
            style: TextStyle(color: ClinicTheme.textSecondary),
          ),
          const SizedBox(height: 24),
          Expanded(
            child: StreamBuilder<ClinicRows>(
              stream: encounters,
              builder: (context, snap) {
                final rows = snap.data ?? const [];
                if (rows.isEmpty) {
                  return const Card(
                    child: Padding(
                      padding: EdgeInsets.all(20),
                      child: Text(
                        'No encounters yet. Seed the demo world (backend/seed_clinic_demo.py) '
                        'or record an encounter — drafts from the scribe agent land here.',
                        style: TextStyle(color: ClinicTheme.textSecondary),
                      ),
                    ),
                  );
                }
                return ListView.separated(
                  itemCount: rows.length,
                  separatorBuilder: (_, __) => const SizedBox(height: 10),
                  itemBuilder: (context, i) => _EncounterCard(row: rows[i]),
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}

class _EncounterCard extends StatelessWidget {
  const _EncounterCard({required this.row});

  final Map<String, dynamic> row;

  @override
  Widget build(BuildContext context) {
    final scribe = (row['scribe_draft'] as Map<String, dynamic>?) ?? const {};
    final status = (scribe['status'] as String?) ?? 'none';
    final sections = (scribe['sections'] as Map<String, dynamic>?) ?? const {};
    final type = (row['type'] as String?) ?? 'encounter';
    final patient = (row['patient_id'] as String?) ?? '?';

    final (icon, color, label) = switch (status) {
      'draft' => (Icons.pending_outlined, ClinicTheme.warningAmber, 'Draft awaiting review'),
      'reviewed' => (Icons.task_alt, ClinicTheme.malachite, 'Reviewed'),
      _ => (Icons.graphic_eq_outlined, ClinicTheme.textSecondary, 'No draft yet — ask the agent to draft it'),
    };

    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Icon(icon, color: color),
                const SizedBox(width: 10),
                Expanded(
                  child: Text('$type — patient $patient',
                      style: const TextStyle(fontWeight: FontWeight.w700)),
                ),
                Text(label, style: TextStyle(color: color, fontSize: 12)),
              ],
            ),
            if (sections.isNotEmpty) ...[
              const SizedBox(height: 12),
              ...sections.entries.map((e) => _SoapSectionItem(
                    title: _capitalize(e.key),
                    content: e.value.toString(),
                    transcript: (row['transcript_text'] as String?) ?? '',
                  )),
            ],
            const SizedBox(height: 12),
            Row(
              mainAxisAlignment: MainAxisAlignment.end,
              children: [
                if (sections.isNotEmpty)
                  OutlinedButton.icon(
                    icon: const Icon(Icons.copy_all_outlined, size: 16, color: ClinicTheme.malachite),
                    label: const Text('Copy EHR Note', style: TextStyle(color: ClinicTheme.malachite, fontSize: 13)),
                    style: OutlinedButton.styleFrom(
                      side: const BorderSide(color: ClinicTheme.malachite),
                    ),
                    onPressed: () => _copyEhrFormat(context, sections, patient),
                  ),
                const SizedBox(width: 8),
                if ((row['transcript_text'] as String?)?.isNotEmpty ?? false)
                  TextButton.icon(
                    icon: const Icon(Icons.link, size: 16, color: ClinicTheme.malachite),
                    label: const Text('Linked Evidence (View Source)',
                        style: TextStyle(color: ClinicTheme.malachite, fontSize: 13)),
                    onPressed: () => _showEvidenceModal(
                      context,
                      title: 'Encounter Transcript Evidence',
                      transcript: row['transcript_text'] as String,
                    ),
                  ),
                const SizedBox(width: 8),
                if (status == 'draft')
                  FilledButton.icon(
                    icon: const Icon(Icons.task_alt, size: 18),
                    label: const Text('Mark reviewed'),
                    onPressed: () => _markReviewed(context),
                  ),
              ],
            ),
          ],
        ),
      ),
    );
  }

  void _copyEhrFormat(BuildContext context, Map<String, dynamic> sections, String patientId) {
    final sub = sections['subjective'] ?? 'Not documented';
    final obj = sections['objective'] ?? 'Not documented';
    final ass = sections['assessment'] ?? 'Not documented';
    final pln = sections['plan'] ?? 'Not documented';

    final text = '''=== OPHTHALMIC CLINICAL ENCOUNTER NOTE ===
Patient ID: $patientId
Date: ${DateTime.now().toLocal().toString().split('.')[0]}
Provider: Dr. Miller, OD

[SUBJECTIVE]
$sub

[OBJECTIVE]
$obj

[ASSESSMENT]
$ass

[PLAN]
$pln

Electronically signed via GozVision Ambient Scribe.''';

    Clipboard.setData(ClipboardData(text: text));
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('✓ Copied to clipboard in EHR format (Epic / Eyefinity ready)'),
        backgroundColor: ClinicTheme.malachite,
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  void _showEvidenceModal(BuildContext context, {required String title, required String transcript, String? highlight}) {
    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: ClinicTheme.cardBackground,
        title: Row(
          children: [
            const Icon(Icons.verified_outlined, color: ClinicTheme.malachite),
            const SizedBox(width: 8),
            Text(title, style: const TextStyle(fontSize: 18, color: ClinicTheme.textPrimary)),
          ],
        ),
        content: SizedBox(
          width: 580,
          child: SingleChildScrollView(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text(
                  'Grounding verification: exact conversation snippet matching this clinical assessment.',
                  style: TextStyle(fontSize: 12, color: ClinicTheme.textSecondary),
                ),
                const SizedBox(height: 12),
                Container(
                  padding: const EdgeInsets.all(14),
                  decoration: BoxDecoration(
                    color: Colors.black.withOpacity(0.3),
                    borderRadius: BorderRadius.circular(8),
                    border: Border.all(color: Colors.white10),
                  ),
                  child: SelectableText(
                    transcript,
                    style: const TextStyle(
                      fontFamily: 'monospace',
                      fontSize: 13,
                      height: 1.5,
                      color: ClinicTheme.textPrimary,
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx),
            child: const Text('Close'),
          ),
        ],
      ),
    );
  }

  Future<void> _markReviewed(BuildContext context) async {
    final uid = Supabase.instance.client.auth.currentUser?.id ?? 'unknown';
    final updated = {
      ...(row['scribe_draft'] as Map<String, dynamic>? ?? const {}),
      'status': 'reviewed',
      'reviewedBy': uid,
      'reviewedAt': DateTime.now().toUtc().toIso8601String(),
    };
    await Supabase.instance.client
        .from('encounters')
        .update({'scribe_draft': updated}).eq('id', row['id'] as String);
  }

  String _capitalize(String s) =>
      s.isEmpty ? s : '${s[0].toUpperCase()}${s.substring(1)}';
}

class _SoapSectionItem extends StatelessWidget {
  const _SoapSectionItem({
    required this.title,
    required this.content,
    required this.transcript,
  });

  final String title;
  final String content;
  final String transcript;

  @override
  Widget build(BuildContext context) {
    // Detect key optometric measurements (IOP, OD, OS, VA, 20/XX, mmHg)
    final hasMetrics = RegExp(r'\b(IOP|OD|OS|OU|VA|20/\d+|\d+\s*mmHg)\b', caseSensitive: false).hasMatch(content);

    return Container(
      margin: const EdgeInsets.only(bottom: 8),
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
        color: ClinicTheme.surfaceDark.withOpacity(0.5),
        borderRadius: BorderRadius.circular(6),
        border: Border.all(color: Colors.white.withOpacity(0.06)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Text(
                title.toUpperCase(),
                style: const TextStyle(
                  color: ClinicTheme.malachite,
                  fontWeight: FontWeight.w700,
                  fontSize: 12,
                  letterSpacing: 0.8,
                ),
              ),
              const Spacer(),
              if (hasMetrics && transcript.isNotEmpty)
                Tooltip(
                  message: 'Click to verify IOP / Acuity / Findings in transcript',
                  child: InkWell(
                    onTap: () {
                      showDialog(
                        context: context,
                        builder: (ctx) => AlertDialog(
                          backgroundColor: ClinicTheme.cardBackground,
                          title: Text('Linked Evidence: $title',
                              style: const TextStyle(color: ClinicTheme.textPrimary)),
                          content: SizedBox(
                            width: 500,
                            child: SingleChildScrollView(
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Text('Clinical Note Extract:\n$content',
                                      style: const TextStyle(
                                          fontWeight: FontWeight.w600,
                                          color: ClinicTheme.malachite)),
                                  const Divider(height: 24),
                                  const Text('Source Encounter Transcript:',
                                      style: TextStyle(color: ClinicTheme.textSecondary)),
                                  const SizedBox(height: 8),
                                  SelectableText(transcript,
                                      style: const TextStyle(
                                          fontFamily: 'monospace', fontSize: 13)),
                                ],
                              ),
                            ),
                          ),
                          actions: [
                            TextButton(
                              onPressed: () => Navigator.pop(ctx),
                              child: const Text('Verified'),
                            ),
                          ],
                        ),
                      );
                    },
                    borderRadius: BorderRadius.circular(4),
                    child: Padding(
                      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                      child: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: const [
                          Icon(Icons.check_circle_outline, size: 14, color: ClinicTheme.malachite),
                          SizedBox(width: 4),
                          Text('Verify Quote', style: TextStyle(color: ClinicTheme.malachite, fontSize: 11)),
                        ],
                      ),
                    ),
                  ),
                ),
            ],
          ),
          const SizedBox(height: 4),
          SelectableText(
            content,
            style: const TextStyle(color: ClinicTheme.textPrimary, fontSize: 13, height: 1.4),
          ),
        ],
      ),
    );
  }
}
